WITH cleaned AS (SELECT id, channel, discount_pct, DATEDIFF(CURRENT_DATE(), ends_on) AS days_since_ends_on FROM promotions WHERE channel IS NOT NULL) SELECT id, discount_pct, days_since_ends_on, SUM(days_since_ends_on) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_days_since_ends_on, LAG(days_since_ends_on, 1) OVER (PARTITION BY channel ORDER BY discount_pct, id) AS prev_days_since_ends_on, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) AS discount_pct_share, LEAD(days_since_ends_on, 1, 0) OVER (PARTITION BY channel ORDER BY discount_pct, id) AS next_days_since_ends_on, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY days_since_ends_on, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_3_prior FROM cleaned WHERE days_since_ends_on >= 61;
